	return cmd
}

func newWhyCmd() *cobra.Command {
	var jsonFlag bool
	var lineFlag string

	cmd := &cobra.Command{
		Use: "why <file>[:line]",
		// Hidden from `entire help` while the feature is still maturing —
		// advertised under `entire labs`, and `entire why` / `entire why
		// --help` keep working normally.
		Hidden:  true,
		Short:   "Show why a line exists",
		Long:    "Explain the commit, checkpoint, prompt, and session behind a file or line.\n\nTarget a specific line with <file>:12 or the --line flag.",
		Example: "  entire why src/auth.go:42\n  entire why src/auth.go:42 --json",
		Args:    cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runAttributionWhy(cmd.Context(), cmd.OutOrStdout(), args[0], attributionWhyOptions{
				LineFlag: lineFlag,
				JSON:     jsonFlag,
			})
		},
	}

	cmd.Flags().StringVar(&lineFlag, "line", "", "Explain a specific line, for example 12 (same as <file>:12)")
	cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output explanation as JSON")
	return cmd
}

type attributionBlameOptions struct {
	LineFlag string
---
	// Verbosity / transcript output modes are mutually exclusive
	cmd.MarkFlagsMutuallyExclusive("short", "full", "raw-transcript", "transcript", "json")
	// --repo reads another repo over HTTP: --commit resolves against local
	// history, --session filters the local list view, --search-all walks local
	// commits, and --generate would write a summary the foreign repo never
	// sees.
	cmd.MarkFlagsMutuallyExclusive("repo", "commit")
	cmd.MarkFlagsMutuallyExclusive("repo", "session")
	cmd.MarkFlagsMutuallyExclusive("repo", "generate")
	cmd.MarkFlagsMutuallyExclusive("repo", "search-all")
	// --generate and --raw-transcript are incompatible (summary would be generated but not shown)
	cmd.MarkFlagsMutuallyExclusive("generate", "raw-transcript")
	// --generate is a write op; export modes are reader-only
	cmd.MarkFlagsMutuallyExclusive("generate", "json")
	cmd.MarkFlagsMutuallyExclusive("generate", "transcript")

